const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry Definitions
  const namibia = ee.FeatureCollection('FAO/GAUL/2015/level0').filter(ee.Filter.eq('ADM0_NAME', 'Namibia'));
  const zimbabwe = ee.FeatureCollection('FAO/GAUL/2015/level0').filter(ee.Filter.eq('ADM0_NAME', 'Zimbabwe'));

  // 2. Data Acquisition - MODIS NDVI
  const modisCol = ee.ImageCollection('MODIS/006/MOD13Q1').select('NDVI');

  // 2019 period
  const period2019 = modisCol.filterDate('2019-02-21', '2019-02-28');
  const period2019Size = period2019.size().getInfo();

  // Baseline period (2003-2017)
  const baselineCol = modisCol.filterDate('2003-02-21', '2017-02-28')
    .filter(ee.Filter.calendarRange(51, 59, 'day_of_year')); // Feb 21-28 equivalent

  const baselineSize = baselineCol.size().getInfo();

  console.log(`2019 Images: ${period2019Size}, Baseline Images: ${baselineSize}`);

  // Check for empty collections
  if (period2019Size === 0 || baselineSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean NDVI
  const ndvi2019 = period2019.mean().multiply(0.0001); // Scale factor
  const baselineMean = baselineCol.mean().multiply(0.0001);

  // Calculate anomalies
  const anomalyNamibia = ndvi2019.subtract(baselineMean).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: namibia,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI');

  const anomalyZimbabwe = ndvi2019.subtract(baselineMean).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: zimbabwe,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI');

  const [anomNam, anomZim] = await Promise.all([
    anomalyNamibia.getInfo(),
    anomalyZimbabwe.getInfo()
  ]);

  // Check for valid pixels
  if (anomNam === null || anomZim === null) {
    console.log("No valid pixels in one or both countries.");
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation errors
  if (isNaN(anomNam) || isNaN(anomZim) || Math.abs(anomNam) > 1 || Math.abs(anomZim) > 1) {
    console.log("Invalid NDVI anomaly values detected.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 4. Analysis - Compare anomalies (more negative = worse)
  console.log(`Namibia anomaly: ${anomNam.toFixed(4)}, Zimbabwe anomaly: ${anomZim.toFixed(4)}`);

  if (anomNam < anomZim) {
    console.log("<answer>A</answer>"); // Namibia worse than Zimbabwe
  } else {
    console.log("<answer>B</answer>"); // Zimbabwe worse or equal to Namibia
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
